370	/* ---- background inference worker: shared state -----------------------------
371	 * Declared up here because BOTH the recognize loop and Enroll's Capture hand
372	 * work to the worker. Inference MUST NOT run on the UI task: that task's stack
373	 * is in PSRAM, and running the ESP-NN/TFLM Invoke on a PSRAM stack wedges the
374	 * SoC (console goes dead, "semaphore timeout") -- the same trap the flash model
375	 * loader hit. A pthread's stack is heap/internal RAM, where it runs fine.
376	 * Protocol: 0 idle -> 1 request -> 2 busy -> 3 done -> 0. */
377	static struct velapaw_frame   g_inf_frame;
378	static float                  g_inf_emb[VELAPAW_EMBED_DIM];
379	static struct velapaw_match   g_inf_m;
380	static uint32_t               g_inf_us;
381	static volatile int           g_inf_state;  /* 0 idle,1 request,2 busy,3 done */
382	static volatile int           g_inf_mode;   /* 0 = recognize, 1 = enroll capture */
383	static int                    g_cap_pending;/* an enroll capture is in flight */
384	
385	static void cam_grab(struct velapaw_frame *f)
386	{
387	  velapaw_camera_get_frame(f);
388	  if (++g_cap_n % 200 == 0)
389	    {
390	      printf("velapaw/cam: capture #%lu\n", g_cap_n);
391	    }
392	}
