395	 * appetite / alert  (relative to each pet's DAILY LIMIT = the ration the
396	 * owner set, not a rolling average)
397	 ****************************************************************************/
398	
399	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
400	 * at the limit). 100% = ate its full daily allowance. */
401	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
402	{
403	  int today = velapaw_store_today_total(id);
404	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
405	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
406	}
407	
408	/* appetite-drop alert: the last completed day was under half the daily limit. */
409	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
410	{
411	  int yesterday = velapaw_store_day_total(id, 1);
412	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
413	}
