454	static void do_capture(void)
455	{
456	  if (g_nsamp >= MAX_SHOTS)
457	    {
458	      return;
459	    }
460	  if (g_inf_state != 0 || g_cap_pending)
461	    {
462	      return;                       /* an inference is already in flight */
463	    }
464	
465	  /* Grab the frame here (cheap, ~ms), but hand the INFERENCE to the worker.
466	   * Running embed() inline on this task wedged the SoC -- see the note on the
467	   * worker state above. The loop picks the result up when g_inf_state == 3. */
468	  cam_grab(&g_inf_frame);
469	  g_inf_mode    = 1;                /* enroll capture: embed, don't match */
470	  g_cap_pending = 1;
471	  g_inf_state   = 1;                /* -> worker */
472	  lv_label_set_text(g_sample_lbl, T(S_CAPTURING));
473	}
