1708	/* ---- background inference worker -----------------------------------------
1709	 * Runs the ~1.3s embed()+match() OFF the UI thread so touch + LVGL stay live
1710	 * while the model runs. Single producer (UI loop) / single consumer (worker),
1711	 * coordinated by g_inf_state: 0 idle -> 1 request -> 2 busy -> 3 done -> 0.
1712	 * The UI pauses camera preview capture while state != 0 so the shared frame
1713	 * buffer the worker reads is never overwritten mid-inference.
1714	 * (State lives near the top of the file -- Capture needs it too.) */
1715	
1716	static void *recog_worker(void *arg)
1717	{
1718	  (void)arg;
1719	  for (;;)
1720	    {
1721	      if (g_inf_state != 1) { usleep(5000); continue; }
1722	      g_inf_state = 2;
1723	      g_be->embed(&g_inf_frame, g_inf_emb, VELAPAW_EMBED_DIM);
1724	      g_inf_us = g_be->last_latency_us();
1725	      if (g_inf_mode == 0)
1726	        {
1727	          velapaw_identity_match(g_inf_emb, &g_inf_m);  /* recognize only */
1728	        }
1729	      g_inf_state = 3;
1730	    }
1731	  return NULL;
1732	}
