    {
      return;
    }

  g_voice_shown = want;
  lv_obj_set_style_text_color(g_voice_lbl,
                              lv_color_hex(want == 2 ? COL_DIM : COL_COOL), 0);
  lv_label_set_text(g_voice_lbl,
                    want == 2 ? T(S_VOICE_OFF) :
