1967	  today = velapaw_store_today_total(g_cand);
1968	  if (today >= pet->daily_limit_g)
1969	    {
1970	      lv_obj_set_style_text_color(g_voice_lbl, lv_color_hex(COL_COOL), 0);
1971	      lv_label_set_text_fmt(g_voice_lbl, T(S_LIMIT_HIT_FMT),
1972	                            today, pet->daily_limit_g);
1973	      return;
1974	    }
1975	
1976	  /* Trim so the day never exceeds the owner's cap -- the same arithmetic the
1977	   * scheduled path uses, because the cap is a property of the pet, not of the
1978	   * route the food took. */
1979	
1980	  remaining = pet->daily_limit_g - today;
1981	  amount    = (pet->portion_g < remaining) ? pet->portion_g : remaining;
1982	
1983	  velapaw_feeder_dispense(amount);
1984	
1985	  { struct timespec _w;
1986	    clock_gettime(CLOCK_REALTIME, &_w);
1987	    struct velapaw_feed_event ev =
1988	      { g_cand, (time_t)_w.tv_sec, amount, g_voice_score, g_be->name };
1989	    velapaw_store_log_feeding(&ev); }
1990	
1991	  g_last_fed[g_cand] = mono_ms() / 1000;
1992	
1993	  /* Deliberately does NOT mark a meal slot fed (g_meal_fed_day).  This is an
1994	   * off-schedule treat the owner asked for out loud; consuming a scheduled
1995	   * meal would mean the pet silently loses the meal it was going to get, and
1996	   * the owner never said that.  The daily limit above is what stops this from
1997	   * being unbounded. */
1998	
1999	  lv_obj_set_style_text_color(g_voice_lbl, lv_color_hex(COL_FED), 0);
2000	  lv_label_set_text_fmt(g_voice_lbl, T(S_VOICE_FED_FMT), amount,
2001	                        velapaw_store_today_total(g_cand),
2002	                        pet->daily_limit_g);
2003	
2004	  printf("velapaw/voice: fed %s %dg by voice (%.2f)\n",
2005	         pet->name, amount, (double)g_voice_score);
2006	}
