1	/****************************************************************************
2	 * VelaPaw - keyword spotting implementation (Phase 1.5)
3	 *
4	 * Two interpreters, run back to back:
5	 *
6	 *   audio (int16, 480 samples)
7	 *       -> audio_preprocessor_int8.tflite   -> 40 int8 mel features
8	 *       (repeated 49x with a 320-sample stride)
9	 *   features (int8, 49 x 40)
10	 *       -> micro_speech_quantized.tflite    -> 4 int8 logits
11	 *
12	 * Both models are linked as rodata from voice/gen/ (27.5 KB combined), NOT
13	 * loaded from flash like the 1.4 MB pet model -- they fit the DROM0 window
14	 * comfortably.
15	 *
16	 * printf, not MicroPrintf: the app is built with -DTF_LITE_STRIP_ERROR_STRINGS
17	 * and this module has no reason to depend on which side of that if/else the
18	 * vendored library landed on.
19	 ****************************************************************************/
20	
21	/****************************************************************************
22	 * Included Files
23	 ****************************************************************************/
24	
25	#include <nuttx/config.h>
26	
27	#include <stdio.h>
28	#include <string.h>
29	#include <errno.h>
30	#include <time.h>
31	#include <algorithm>
32	
33	#include <nuttx/kmalloc.h>
34	
35	#include "tensorflow/lite/core/c/common.h"
36	#include "tensorflow/lite/micro/micro_interpreter.h"
37	#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
38	#include "tensorflow/lite/schema/schema_generated.h"
39	
40	#include "kws.h"
41	
42	#include "micro_speech_quantized_model_data.h"
43	#include "audio_preprocessor_int8_model_data.h"
44	
45	#ifdef CONFIG_VELAPAW_KWS_SELFTEST
46	#  include "yes_30ms_audio_data.h"
47	#  include "no_30ms_audio_data.h"
48	#  include "yes_1000ms_audio_data.h"
49	#  include "no_1000ms_audio_data.h"
50	#  include "silence_1000ms_audio_data.h"
51	#endif
52	
53	/****************************************************************************
54	 * Pre-processor Definitions
55	 ****************************************************************************/
56	
57	/* Generous to begin with, deliberately.  A failed AllocateTensors costs a
58	 * whole build/flash cycle to discover, whereas over-allocating costs heap we
59	 * have (MM_REGIONS=2 puts octal PSRAM in the general heap).  Both are printed
60	 * at init as arena_used_bytes(); shrink these to the measured values once
61	 * they have been read off the console.
62	 *
63	 * Upstream sizes ONE arena at 28584 for whichever model is larger, because it
64	 * never has both alive at once.  We do, hence two.
65	 */
66	
67	/* Measured on hardware (build 36): frontend 9840 B, classifier 6916 B.  Both
68	 * are fixed by the graph, not the input, so these are exact rather than
69	 * typical -- sized here with ~20% headroom.  Still printed at init; if either
70	 * number ever moves, the model changed.
71	 */
72	
73	#define KWS_FRONTEND_ARENA   (12 * 1024)
74	#define KWS_CLASSIFIER_ARENA (8 * 1024)
75	
76	/****************************************************************************
77	 * Private Types
78	 ****************************************************************************/
79	
80	using FrontendOpResolver   = tflite::MicroMutableOpResolver<18>;
81	using ClassifierOpResolver = tflite::MicroMutableOpResolver<4>;
82	
83	/****************************************************************************
84	 * Private Data
85	 ****************************************************************************/
86	
87	static bool g_ready = false;
88	
89	static uint8_t *g_frontend_arena   = nullptr;
90	static uint8_t *g_classifier_arena = nullptr;
91	
92	static tflite::MicroInterpreter *g_frontend   = nullptr;
93	static tflite::MicroInterpreter *g_classifier = nullptr;
94	
95	static size_t g_frontend_used   = 0;
96	static size_t g_classifier_used = 0;
97	
98	/* One 49x40 feature map, reused across calls.  1960 bytes -- small enough to
99	 * keep in .bss rather than juggling ownership with the caller.
100	 */
101	
102	static int8_t g_features[VELAPAW_KWS_FEATURE_COUNT][VELAPAW_KWS_FEATURE_SIZE];
103	
104	static const char *g_label_names[VELAPAW_KWS_CATEGORIES] =
105	{
106	  "silence", "unknown", "yes", "no"
107	};
108	
109	/****************************************************************************
110	 * Private Functions
111	 ****************************************************************************/
112	
113	static uint32_t kws_now_ms(void)
114	{
115	  struct timespec ts;
116	
117	  clock_gettime(CLOCK_MONOTONIC, &ts);
118	  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
119	}
120	
121	/* Both graphs are int8 quantised but take different input types (int16 audio
122	 * vs int8 features), so shapes are checked rather than assumed.  A silent
123	 * shape mismatch here would surface much later as "the model is inaccurate",
124	 * which is a far worse thing to debug.
125	 */
126	
127	static int kws_check_tensor(TfLiteTensor *t, const char *what,
128	                            TfLiteType type, int last_dim)
129	{
130	  if (t == nullptr)
131	    {
132	      printf("kws: %s tensor is NULL\n", what);
133	      return -EINVAL;
134	    }
135	
136	  if (t->type != type)
137	    {
138	      printf("kws: %s tensor type %d, expected %d\n",
139	             what, (int)t->type, (int)type);
140	      return -EINVAL;
141	    }
142	
143	  if (t->dims->data[t->dims->size - 1] != last_dim)
144	    {
145	      printf("kws: %s tensor last dim %d, expected %d\n",
146	             what, (int)t->dims->data[t->dims->size - 1], last_dim);
147	      return -EINVAL;
148	    }
149	
150	  return 0;
151	}
152	
153	/* Registered once and reused across interpreter rebuilds.  The interpreter
154	 * holds a reference to this, so it must outlive every interpreter built from
155	 * it -- a function-local static does exactly that.
156	 *
157	 * -fno-threadsafe-statics means no __cxa_guard_acquire is emitted here.  That
158	 * call never returns on this target; it is why the whole signal library has to
159	 * be built with the same flag (board/patches/tflm-signal.py).
160	 */
161	
162	static FrontendOpResolver *kws_frontend_ops(void)
163	{
164	  static FrontendOpResolver resolver;
165	  static bool registered = false;
166	
167	  if (registered)
168	    {
169	      return &resolver;
170	    }
171	
172	  /* The nine signal ops below are why the library build needs
173	   * signal/micro/kernels and signal/src: the vendored tflite-micro Makefile
174	   * globs only tensorflow/lite/..., so without that these link as undefined.
175	   */
176	
177	  if (resolver.AddReshape()                        != kTfLiteOk ||
178	      resolver.AddCast()                           != kTfLiteOk ||
179	      resolver.AddStridedSlice()                   != kTfLiteOk ||
180	      resolver.AddConcatenation()                  != kTfLiteOk ||
181	      resolver.AddMul()                            != kTfLiteOk ||
182	      resolver.AddAdd()                            != kTfLiteOk ||
183	      resolver.AddDiv()                            != kTfLiteOk ||
184	      resolver.AddMinimum()                        != kTfLiteOk ||
185	      resolver.AddMaximum()                        != kTfLiteOk ||
186	      resolver.AddWindow()                         != kTfLiteOk ||
187	      resolver.AddFftAutoScale()                   != kTfLiteOk ||
188	      resolver.AddRfft()                           != kTfLiteOk ||
189	      resolver.AddEnergy()                         != kTfLiteOk ||
190	      resolver.AddFilterBank()                     != kTfLiteOk ||
191	      resolver.AddFilterBankSquareRoot()           != kTfLiteOk ||
192	      resolver.AddFilterBankSpectralSubtraction()  != kTfLiteOk ||
193	      resolver.AddPCAN()                           != kTfLiteOk ||
194	      resolver.AddFilterBankLog()                  != kTfLiteOk)
195	    {
196	      printf("kws: frontend op registration failed\n");
197	      return nullptr;
198	    }
199	
200	  registered = true;
201	  return &resolver;
202	}
203	
204	/* Build (or REbuild) the frontend interpreter on the existing arena.
205	 *
206	 * Rebuilding is the only way to clear the frontend's carried state.  The
207	 * spectral-subtraction and PCAN noise estimates do NOT live in variable
208	 * tensors -- they are in each node's user_data, and the sole thing that zeroes
209	 * them is ResetState() inside the kernel's Prepare(), which runs as part of
210	 * AllocateTensors().  MicroInterpreter::Reset() resets variable tensors and
211	 * would silently NOT touch these.  Upstream sidesteps the whole question by
212	 * constructing a fresh interpreter per utterance; this is that, made explicit.
213	 *
214	 * The arena is reused across rebuilds, exactly as upstream reuses its g_arena.
215	 */
216	
217	static int kws_build_frontend(void)
218	{
219	  const tflite::Model *model =
220	    tflite::GetModel(g_audio_preprocessor_int8_model_data);
221	
222	  FrontendOpResolver *ops = kws_frontend_ops();
223	  if (ops == nullptr)
224	    {
225	      return -EINVAL;
226	    }
227	
228	  delete g_frontend;
229	  g_frontend = nullptr;
230	
231	  tflite::MicroInterpreter *interp =
232	    new tflite::MicroInterpreter(model, *ops, g_frontend_arena,
233	                                 KWS_FRONTEND_ARENA);
234	
235	  if (interp == nullptr)
236	    {
237	      printf("kws: frontend interpreter alloc failed\n");
238	      return -ENOMEM;
239	    }
240	
241	  if (interp->AllocateTensors() != kTfLiteOk)
242	    {
243	      printf("kws: frontend AllocateTensors FAILED (arena %d B too small?)\n",
244	             KWS_FRONTEND_ARENA);
245	      delete interp;
246	      return -ENOMEM;
247	    }
248	
249	  g_frontend      = interp;
250	  g_frontend_used = interp->arena_used_bytes();
251	  return 0;
252	}
253	
254	static int kws_init_frontend(void)
255	{
256	  const tflite::Model *model =
257	    tflite::GetModel(g_audio_preprocessor_int8_model_data);
258	  int ret;
259	
260	  if (model->version() != TFLITE_SCHEMA_VERSION)
261	    {
262	      printf("kws: frontend schema %u, expected %u\n",
263	             (unsigned)model->version(), (unsigned)TFLITE_SCHEMA_VERSION);
264	      return -EINVAL;
265	    }
266	
267	  g_frontend_arena = (uint8_t *)kmm_memalign(16, KWS_FRONTEND_ARENA);
268	  if (g_frontend_arena == nullptr)
269	    {
270	      printf("kws: frontend arena alloc %d B failed\n", KWS_FRONTEND_ARENA);
271	      return -ENOMEM;
272	    }
273	
274	  ret = kws_build_frontend();
275	  if (ret < 0)
276	    {
277	      return ret;
278	    }
279	
280	  if (kws_check_tensor(g_frontend->input(0), "frontend in", kTfLiteInt16,
281	                       VELAPAW_KWS_FRAME_SAMPLES) < 0 ||
282	      kws_check_tensor(g_frontend->output(0), "frontend out", kTfLiteInt8,
283	                       VELAPAW_KWS_FEATURE_SIZE) < 0)
284	    {
285	      return -EINVAL;
286	    }
287	
288	  printf("kws: frontend ready, arena used %u/%d B\n",
289	         (unsigned)g_frontend_used, KWS_FRONTEND_ARENA);
290	  return 0;
291	}
292	
293	static int kws_init_classifier(void)
294	{
295	  const tflite::Model *model =
296	    tflite::GetModel(g_micro_speech_quantized_model_data);
297	
298	  if (model->version() != TFLITE_SCHEMA_VERSION)
299	    {
300	      printf("kws: classifier schema %u, expected %u\n",
301	             (unsigned)model->version(), (unsigned)TFLITE_SCHEMA_VERSION);
302	      return -EINVAL;
303	    }
304	
305	  g_classifier_arena = (uint8_t *)kmm_memalign(16, KWS_CLASSIFIER_ARENA);
306	  if (g_classifier_arena == nullptr)
307	    {
308	      printf("kws: classifier arena alloc %d B failed\n",
309	             KWS_CLASSIFIER_ARENA);
310	      return -ENOMEM;
311	    }
312	
313	  static ClassifierOpResolver resolver;
314	
315	  if (resolver.AddReshape()         != kTfLiteOk ||
316	      resolver.AddFullyConnected()  != kTfLiteOk ||
317	      resolver.AddDepthwiseConv2D() != kTfLiteOk ||
318	      resolver.AddSoftmax()         != kTfLiteOk)
319	    {
320	      printf("kws: classifier op registration failed\n");
321	      return -EINVAL;
322	    }
323	
324	  static tflite::MicroInterpreter interp(model, resolver, g_classifier_arena,
325	                                         KWS_CLASSIFIER_ARENA);
326	
327	  if (interp.AllocateTensors() != kTfLiteOk)
328	    {
329	      printf("kws: classifier AllocateTensors FAILED (arena %d B too small?)\n",
330	             KWS_CLASSIFIER_ARENA);
331	      return -ENOMEM;
332	    }
333	
334	  g_classifier      = &interp;
335	  g_classifier_used = interp.arena_used_bytes();
336	
337	  if (kws_check_tensor(interp.input(0), "classifier in", kTfLiteInt8,
338	                       VELAPAW_KWS_FEATURE_COUNT *
339	                       VELAPAW_KWS_FEATURE_SIZE) < 0 ||
340	      kws_check_tensor(interp.output(0), "classifier out", kTfLiteInt8,
341	                       VELAPAW_KWS_CATEGORIES) < 0)
342	    {
343	      return -EINVAL;
344	    }
345	
346	  printf("kws: classifier ready, arena used %u/%d B\n",
347	         (unsigned)g_classifier_used, KWS_CLASSIFIER_ARENA);
348	  return 0;
349	}
350	
351	/* Build the 49x40 feature map.  One interpreter invocation per frame -- the
352	 * frontend graph is stateful across calls (spectral subtraction and PCAN both
353	 * carry noise estimates forward), so frames MUST be fed in time order and the
354	 * interpreter must not be rebuilt between them.
355	 */
356	
357	static int kws_generate_features(const int16_t *audio, size_t nsamples)
358	{
359	  TfLiteTensor *input  = g_frontend->input(0);
360	  TfLiteTensor *output = g_frontend->output(0);
361	  size_t remaining     = nsamples;
362	  int frame            = 0;
363	
364	  while (remaining >= VELAPAW_KWS_FRAME_SAMPLES &&
365	         frame < VELAPAW_KWS_FEATURE_COUNT)
366	    {
367	      std::copy_n(audio, VELAPAW_KWS_FRAME_SAMPLES,
368	                  tflite::GetTensorData<int16_t>(input));
369	
370	      if (g_frontend->Invoke() != kTfLiteOk)
371	        {
372	          printf("kws: frontend Invoke failed at frame %d\n", frame);
373	          return -EIO;
374	        }
375	
376	      std::copy_n(tflite::GetTensorData<int8_t>(output),
377	                  VELAPAW_KWS_FEATURE_SIZE, g_features[frame]);
378	
379	      frame     += 1;
380	      audio     += VELAPAW_KWS_STRIDE_SAMPLES;
381	      remaining -= VELAPAW_KWS_STRIDE_SAMPLES;
382	    }
383	
384	  if (frame != VELAPAW_KWS_FEATURE_COUNT)
385	    {
386	      printf("kws: only %d/%d frames from %u samples\n",
387	             frame, VELAPAW_KWS_FEATURE_COUNT, (unsigned)nsamples);
388	      return -EINVAL;
389	    }
390	
391	  return 0;
392	}
