394	/****************************************************************************
395	 * Public Functions
396	 ****************************************************************************/
397	
398	int velapaw_kws_init(void)
399	{
400	  int ret;
401	
402	  if (g_ready)
403	    {
404	      return 0;
405	    }
406	
407	  printf("kws: init (frontend %d B + classifier %d B arenas)\n",
408	         KWS_FRONTEND_ARENA, KWS_CLASSIFIER_ARENA);
409	  fflush(stdout);
410	
411	  ret = kws_init_frontend();
412	  if (ret < 0)
413	    {
414	      return ret;
415	    }
416	
417	  ret = kws_init_classifier();
418	  if (ret < 0)
419	    {
420	      return ret;
421	    }
422	
423	  g_ready = true;
424	  printf("kws: ready\n");
425	  fflush(stdout);
426	  return 0;
427	}
428	
429	int velapaw_kws_reset(void)
430	{
431	  if (!g_ready)
432	    {
433	      return 0;   /* nothing built yet; init() starts clean anyway */
434	    }
435	
436	  /* Frontend only.  The classifier graph (Reshape / FullyConnected /
437	   * DepthwiseConv2D / Softmax) carries nothing between invocations, so
438	   * rebuilding it would cost time and change no result.
439	   */
440	
441	  return kws_build_frontend();
442	}
443	
444	int velapaw_kws_classify(const int16_t *audio, size_t nsamples,
445	                         struct velapaw_kws_result_s *result)
446	{
447	  uint32_t t0;
448	  uint32_t t1;
449	  uint32_t t2;
450	  int ret;
451	  int i;
452	  int best;
453	
454	  if (audio == nullptr || result == nullptr)
455	    {
456	      return -EINVAL;
457	    }
458	
459	  if (!g_ready)
460	    {
461	      ret = velapaw_kws_init();
462	      if (ret < 0)
463	        {
464	          return ret;
465	        }
466	    }
467	
468	  if (nsamples < (size_t)VELAPAW_KWS_MIN_SAMPLES)
469	    {
470	      printf("kws: %u samples, need at least %d\n",
471	             (unsigned)nsamples, VELAPAW_KWS_MIN_SAMPLES);
472	      return -EINVAL;
473	    }
474	
475	  memset(result, 0, sizeof(*result));
476	
477	  t0  = kws_now_ms();
478	  ret = kws_generate_features(audio, nsamples);
479	  if (ret < 0)
480	    {
481	      return ret;
482	    }
483	
484	  t1 = kws_now_ms();
485	
486	  TfLiteTensor *input  = g_classifier->input(0);
487	  TfLiteTensor *output = g_classifier->output(0);
488	
489	  std::copy_n(&g_features[0][0],
490	              VELAPAW_KWS_FEATURE_COUNT * VELAPAW_KWS_FEATURE_SIZE,
491	              tflite::GetTensorData<int8_t>(input));
492	
493	  if (g_classifier->Invoke() != kTfLiteOk)
494	    {
495	      printf("kws: classifier Invoke failed\n");
496	      return -EIO;
497	    }
498	
499	  t2 = kws_now_ms();
500	
501	  /* Dequantise: the graph ends in Softmax, so these sum to ~1.0. */
502	
503	  best = 0;
504	  for (i = 0; i < VELAPAW_KWS_CATEGORIES; i++)
505	    {
506	      result->scores[i] =
507	        (tflite::GetTensorData<int8_t>(output)[i] - output->params.zero_point) *
508	        output->params.scale;
509	
510	      if (result->scores[i] > result->scores[best])
511	        {
512	          best = i;
513	        }
514	    }
515	
516	  result->label      = best;
517	  result->score      = result->scores[best];
518	  result->feature_ms = t1 - t0;
519	  result->infer_ms   = t2 - t1;
520	
521	  return 0;
522	}
523	
524	const char *velapaw_kws_label_name(int label)
525	{
526	  if (label < 0 || label >= VELAPAW_KWS_CATEGORIES)
527	    {
528	      return "?";
529	    }
530	
531	  return g_label_names[label];
532	}
