568	/* One frame only, so kws_generate_features() cannot be reused (it insists on
569	 * a full 49).  This deliberately drives the frontend directly.
570	 */
571	
572	static int kws_selftest_feature(const char *what, const int16_t *audio,
573	                                unsigned int nsamples,
574	                                const int8_t *expected)
575	{
576	  int mismatches = 0;
577	  int i;
578	  int ret;
579	
580	  if (nsamples != (unsigned int)VELAPAW_KWS_FRAME_SAMPLES)
581	    {
582	      printf("kws/selftest: %s has %u samples, expected %d\n",
583	             what, nsamples, VELAPAW_KWS_FRAME_SAMPLES);
584	      return -EINVAL;
585	    }
586	
587	  /* The expected vectors are for a frontend that has processed nothing at all
588	   * beforehand, so each check needs a clean one -- otherwise the first check
589	   * poisons the second with its noise estimate.  Tensor pointers move when the
590	   * interpreter is rebuilt, so they are fetched after this, not before.
591	   */
592	
593	  ret = velapaw_kws_reset();
594	  if (ret < 0)
595	    {
596	      return ret;
597	    }
598	
599	  TfLiteTensor *input  = g_frontend->input(0);
600	  TfLiteTensor *output = g_frontend->output(0);
601	
602	  std::copy_n(audio, VELAPAW_KWS_FRAME_SAMPLES,
603	              tflite::GetTensorData<int16_t>(input));
604	
605	  if (g_frontend->Invoke() != kTfLiteOk)
606	    {
607	      printf("kws/selftest: %s frontend Invoke failed\n", what);
608	      return -EIO;
609	    }
610	
611	  const int8_t *got = tflite::GetTensorData<int8_t>(output);
612	
613	  for (i = 0; i < VELAPAW_KWS_FEATURE_SIZE; i++)
614	    {
615	      if (got[i] != expected[i])
616	        {
617	          if (mismatches < 4)
618	            {
619	              printf("kws/selftest: %s feature[%d] = %d, expected %d\n",
620	                     what, i, (int)got[i], (int)expected[i]);
621	            }
622	
623	          mismatches++;
624	        }
625	    }
626	
627	  if (mismatches != 0)
628	    {
629	      printf("kws/selftest: %s FRONTEND MISMATCH, %d/%d bytes differ\n",
630	             what, mismatches, VELAPAW_KWS_FEATURE_SIZE);
631	      return -EIO;
632	    }
633	
634	  printf("kws/selftest: %s frontend bit-exact (%d/%d)\n",
635	         what, VELAPAW_KWS_FEATURE_SIZE, VELAPAW_KWS_FEATURE_SIZE);
636	  return 0;
637	}
