639	static int kws_selftest_classify(const char *what, const int16_t *audio,
640	                                 unsigned int nsamples, int expected)
641	{
642	  struct velapaw_kws_result_s r;
643	  int ret;
644	  int i;
645	
646	  /* Each clip is independent, and upstream builds a fresh interpreter per
647	   * clip; reset so these numbers are comparable with its published ones.
648	   */
649	
650	  ret = velapaw_kws_reset();
651	  if (ret < 0)
652	    {
653	      return ret;
654	    }
