656	  ret = velapaw_kws_classify(audio, nsamples, &r);
657	  if (ret < 0)
658	    {
659	      printf("kws/selftest: %s classify failed: %d\n", what, ret);
660	      return ret;
661	    }
662	
663	  printf("kws/selftest: %-8s -> %-8s %.3f  (feat %ums, infer %ums)\n",
664	         what, velapaw_kws_label_name(r.label), (double)r.score,
665	         (unsigned)r.feature_ms, (unsigned)r.infer_ms);
666	
667	  for (i = 0; i < VELAPAW_KWS_CATEGORIES; i++)
668	    {
669	      printf("kws/selftest:     %-8s %.4f\n",
670	             velapaw_kws_label_name(i), (double)r.scores[i]);
671	    }
672	
673	  if (r.label != expected)
674	    {
675	      printf("kws/selftest: %s MISCLASSIFIED (expected %s)\n",
676	             what, velapaw_kws_label_name(expected));
677	      return -EIO;
678	    }
679	
680	  return 0;
681	}
