691	      return ret;
692	    }
693	
694	  printf("kws/selftest: ---- frontend bit-exactness ----\n");
695	  fflush(stdout);
696	
697	  /* Every check below resets the frontend first.  It carries a noise estimate
698	   * forward, and the upstream expected vectors assume one that has seen
699	   * nothing else -- without the reset, yes_30ms poisons no_30ms and the second
700	   * check fails on all 40 bytes while the first passes.  That is exactly what
