712	                           g_no_30ms_audio_data_size,
713	                           g_expected_no_feature) < 0)
714	    {
715	      failures++;
716	    }
717	
718	  printf("kws/selftest: ---- end-to-end classification ----\n");
719	  fflush(stdout);
720	
721	  if (kws_selftest_classify("yes", g_yes_1000ms_audio_data,
722	                            g_yes_1000ms_audio_data_size,
723	                            VELAPAW_KWS_YES) < 0)
724	    {
725	      failures++;
726	    }
727	
728	  if (kws_selftest_classify("no", g_no_1000ms_audio_data,
729	                            g_no_1000ms_audio_data_size,
730	                            VELAPAW_KWS_NO) < 0)
731	    {
732	      failures++;
733	    }
734	
735	  if (kws_selftest_classify("silence", g_silence_1000ms_audio_data,
736	                            g_silence_1000ms_audio_data_size,
737	                            VELAPAW_KWS_SILENCE) < 0)
738	    {
739	      failures++;
740	    }
741	
742	  if (failures != 0)
743	    {
744	      printf("kws/selftest: %d CHECK(S) FAILED\n", failures);
