835	  ret = mic_configure(ctx->recfd, AUDIO_TYPE_INPUT);
836	  if (ret < 0)
837	    {
838	      return ret;
839	    }
840	
841	  /* Must read state=1 (PREPARED).  If it reads 0 (OPEN), the CONFIGURE was a
842	   * silent no-op and the record node is still in ES_MODULE_DAC -- which sends
843	   * its buffers to I2S_SEND and starves RX exactly as observed.
844	   */
845	
846	  mic_status(ctx->recfd, "rec cfg");
847	
848	  /* Configured to match the record side.  TX is only ever fed silence here,
849	   * but it generates the clock RX runs on, so its frame geometry has to be
850	   * the same or RX samples at the wrong rate.
851	   */
852	
853	  ret = mic_configure(ctx->playfd, AUDIO_TYPE_OUTPUT);
854	  if (ret < 0)
855	    {
856	      return ret;
857	    }
858	
859	  mic_status(ctx->playfd, "play cfg");
860	
861	  /* Gain goes here, after BOTH configures, deliberately.
862	   *
863	   * pcm0 and pcm_in0 are two independent es8311 priv structs driving ONE
