870	
871	  if (MIC_GAIN_DB >= 0)
872	    {
873	      mic_set_gain(ctx->recfd, MIC_GAIN_DB);
874	    }
875	
876	  /* GETBUFFERINFO is NOT just a query -- it is what arms allocation.
877	   *
878	   * audio.c's AUDIOIOC_GETBUFFERINFO handler copies the driver's reply into
879	   * upper->nbuffers as a side effect, and audio_allocbuffer() opens with
880	   * "if (upper->periods >= upper->nbuffers) return 0;".  Skip the query on a
881	   * device and its nbuffers stays 0, so the very first ALLOCBUFFER on it
882	   * returns 0 -- not a negative errno, literally zero, which reads like
883	   * success to anything checking for < 0.
884	   *
885	   * So it has to be issued on BOTH devices: the counter lives in the
886	   * per-device upper half, and answering for the record node does nothing for
887	   * the playback node.  nxlooper does the same, once per device.
888	   *
889	   * The reply is reported rather than assumed, because 4 x 8192 happens to be
890	   * both the es8311 driver's answer and the CONFIG_AUDIO_* fallback below --
891	   * identical numbers, opposite meanings.
892	   */
893	
894	  ret = ioctl(ctx->recfd, AUDIOIOC_GETBUFFERINFO, (unsigned long)&bufinfo);
895	  micinfo("mic: record GETBUFFERINFO ret=%d\n", ret);
896	  if (ret != OK)
897	    {
898	      bufinfo.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
899	      bufinfo.nbuffers    = CONFIG_AUDIO_NUM_BUFFERS;
900	    }

900	    }
901	
902	  ret = ioctl(ctx->playfd, AUDIOIOC_GETBUFFERINFO,
903	              (unsigned long)&playbufinfo);
904	  micinfo("mic: playback GETBUFFERINFO ret=%d\n", ret);
905	  if (ret != OK)
906	    {
907	      playbufinfo.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
908	      playbufinfo.nbuffers    = CONFIG_AUDIO_NUM_BUFFERS;
909	    }
910	
911	  /* Deliberately ask for more than the driver suggested -- see MIC_WANT_BUFS.
912	   * This also widens the message queue below, since mq_maxmsg is derived from
913	   * this count, which is what a window's worth of un-drained DEQUEUEs needs.
914	   */
915	
916	  if (bufinfo.nbuffers < MIC_WANT_BUFS)
917	    {
918	      bufinfo.nbuffers = MIC_WANT_BUFS;
919	    }
920	
921	  if (bufinfo.nbuffers > MIC_MAX_BUFS)
922	    {
923	      bufinfo.nbuffers = MIC_MAX_BUFS;
924	    }
925	
926	  printf("mic: %d buffers x %d B\n",
927	         (int)bufinfo.nbuffers, (int)bufinfo.buffer_size);
928	
929	  for (i = 0; i < bufinfo.nbuffers; i++)
930	    {
931	      ret = mic_alloc_buffer(ctx->recfd, &ctx->recbufs[i],
932	                             bufinfo.buffer_size);
933	      if (ret < 0)
934	        {
935	          /* Asking past the driver's suggested depth is speculative, so a
936	           * refusal partway through is a legitimate answer rather than a
937	           * failure -- carry on with what was granted.  Below the suggested
938	           * depth it is a real error and still aborts.
939	           */
940	
941	          if (i >= MIC_MIN_BUFS)
942	            {
943	              printf("mic: pool capped at %d buffers (wanted %d, ret %d)\n",
944	                     i, (int)bufinfo.nbuffers, ret);
945	              break;
946	            }
947	
948	          return ret;
949	        }
950	
951	      ctx->nrecbufs = i + 1;
952	    }
953	
954	  ret = mic_alloc_buffer(ctx->playfd, &ctx->playbuf, playbufinfo.buffer_size);
955	  if (ret < 0)
956	    {
957	      return ret;
958	    }
959	
960	  snprintf(ctx->mqname, sizeof(ctx->mqname), "/vpmic%d", (int)getpid());
961	
962	  {
963	    struct mq_attr attr;
964	
965	    attr.mq_maxmsg  = bufinfo.nbuffers + 8;
966	    attr.mq_msgsize = sizeof(struct audio_msg_s);
967	    attr.mq_curmsgs = 0;
968	    attr.mq_flags   = 0;
969	
970	    ctx->mq = mq_open(ctx->mqname, O_RDWR | O_CREAT, 0644, &attr);
971	  }
972	
973	  if (ctx->mq == (mqd_t)-1)
