985	      return -errno;
986	    }
987	
988	  /* Buffers must be in the driver's hands BEFORE START on this codec: START
989	   * is what spawns es8311's worker thread, and the worker looks for work in
990	   * pendq as soon as it runs.  This is the order nxlooper uses and the order
991	   * every working capture on this board has used.
992	   */
993	
994	  ret = mic_arm(ctx);
995	  if (ret < 0)
996	    {
997	      return ret;
998	    }
999	
1000	  /* head must equal nrecbufs here.  That is what proves the buffers got past
1001	   * audio_enqueuebuffer() into es8311's pendq.
1002	   */
1003	
1004	  mic_status(ctx->recfd, "rec enq");
1005	  mic_status(ctx->playfd, "play enq");
1006	
1007	  /* TX starts FIRST.  Without a running TX, RX never sees a bit clock and the
1008	   * dequeue loop blocks until the timeout with zero buffers returned -- RX
1009	   * borrows BCLK/WS from TX in full-duplex mode.  See mic.h.

690	 * worker only calls I2S_RECEIVE when it has a buffer, and i2s_rxdma_start()
691	 * only loads a DMA descriptor when one is pending; on the transmit side
692	 * submitting a buffer is what sets I2S_TX_START.  AUDIOIOC_START, already
693	 * issued once at session open, does neither.
694	 *
695	 * TX is re-primed on every capture even though the clock should still be free
696	 * running from the last one -- patch #16 clears I2S_TX_STOP_EN so BCLK/WS do
697	 * not gate off when the FIFO drains.  One 8192-byte buffer is only 256 ms of
698	 * audio and captures are a full second, so the clock demonstrably outlives the
699	 * data; the re-prime costs nothing and removes the assumption.
700	 */
701	
702	static int mic_arm(struct mic_ctx_s *ctx)
703	{
704	  int ret;
705	  int i;
706	
707	  for (i = 0; i < ctx->nrecbufs; i++)
708	    {
709	      ctx->recbufs[i]->nbytes  = 0;
710	      ctx->recbufs[i]->curbyte = 0;
711	
712	      ret = mic_enqueue(ctx->recfd, ctx->recbufs[i]);
713	      if (ret < 0)
714	        {
715	          printf("mic: enqueue record buffer %d failed: %d\n", i, ret);
716	          return ret;
717	        }
718	    }
719	
720	  memset(ctx->playbuf->samp, 0, ctx->playbuf->nmaxbytes);
721	  ctx->playbuf->nbytes  = ctx->playbuf->nmaxbytes;
722	  ctx->playbuf->curbyte = 0;
723	
724	  ret = mic_enqueue(ctx->playfd, ctx->playbuf);
725	  if (ret < 0)
726	    {
727	      printf("mic: priming TX failed: %d\n", ret);
728	      return ret;
729	    }
730	
731	  return 0;
732	}
