734	/* Run the ADC power-up transient through and throw it away.  See
735	 * MIC_WARMUP_BUFS.  Failure here is not fatal: a warm-up that times out costs
736	 * a dirty first capture, not a broken session.
737	 */
738	
739	static void mic_warmup(struct mic_ctx_s *ctx)
740	{
741	  struct audio_msg_s msg;
742	  struct timespec deadline;
743	  unsigned int prio;
744	  int discarded = 0;
745	  int guard = 0;
746	
747	  while (discarded < MIC_WARMUP_BUFS && guard++ < MIC_WARMUP_BUFS * 4)
748	    {
749	      struct ap_buffer_s *apb;
750	
751	      clock_gettime(CLOCK_REALTIME, &deadline);
752	      deadline.tv_sec += 1;
753	
754	      if (mq_timedreceive(ctx->mq, (char *)&msg, sizeof(msg), &prio,
755	                          &deadline) != sizeof(msg))
756	        {
757	          break;
758	        }
759	
760	      if (msg.msg_id != AUDIO_MSG_DEQUEUE)
761	        {
762	          continue;
763	        }
764	
765	      apb = (struct ap_buffer_s *)msg.u.ptr;
766	      if (apb == NULL || apb == ctx->playbuf)
767	        {
768	          continue;
769	        }
770	
771	      discarded++;
772	      apb->nbytes  = 0;
773	      apb->curbyte = 0;
774	
775	      if (mic_enqueue(ctx->recfd, apb) < 0)
776	        {
777	          break;
778	        }
779	    }
780	
781	  micinfo("mic: warmup discarded %d buffer(s)\n", discarded);
782	}
