1045	/* Full teardown.  Only on shutdown, or to recover from a failed capture --
1046	 * NOT between successful captures, which is the bug this file exists to fix.
1047	 */
1048	
1049	static void mic_session_close(struct mic_ctx_s *ctx)
1050	{
1051	  struct audio_buf_desc_s desc;
1052	  int i;
1053	
1054	  if (ctx->rec_started)
1055	    {
1056	      ioctl(ctx->recfd, AUDIOIOC_STOP, 0);
1057	    }
1058	
1059	  if (ctx->play_started)
1060	    {
1061	      ioctl(ctx->playfd, AUDIOIOC_STOP, 0);
1062	    }
1063	
1064	  /* Must run after STOP and before FREEBUFFER: freeing a buffer the driver is
1065	   * still holding leaves it pointing at released memory.
1066	   */
1067	
1068	  mic_quiesce(ctx);
1069	
1070	  if (ctx->mq_open)
1071	    {
1072	      if (ctx->recfd >= 0)
1073	        {
1074	          ioctl(ctx->recfd, AUDIOIOC_UNREGISTERMQ, (unsigned long)ctx->mq);
1075	        }
1076	
1077	      if (ctx->playfd >= 0)
1078	        {
1079	          ioctl(ctx->playfd, AUDIOIOC_UNREGISTERMQ, (unsigned long)ctx->mq);
1080	        }
1081	    }
1082	
1083	  for (i = 0; i < ctx->nrecbufs; i++)
1084	    {
1085	      if (ctx->recbufs[i] != NULL)
1086	        {
1087	          memset(&desc, 0, sizeof(desc));
1088	          desc.u.buffer = ctx->recbufs[i];
1089	          ioctl(ctx->recfd, AUDIOIOC_FREEBUFFER, (unsigned long)&desc);
1090	          ctx->recbufs[i] = NULL;
1091	        }
1092	    }
1093	
1094	  if (ctx->playbuf != NULL)
1095	    {
1096	      memset(&desc, 0, sizeof(desc));
1097	      desc.u.buffer = ctx->playbuf;
1098	      ioctl(ctx->playfd, AUDIOIOC_FREEBUFFER, (unsigned long)&desc);
1099	      ctx->playbuf = NULL;
1100	    }
1101	
1102	  if (ctx->rec_reserved)
1103	    {
1104	      ioctl(ctx->recfd, AUDIOIOC_RELEASE, 0);
1105	    }
1106	
1107	  if (ctx->play_reserved)
1108	    {
1109	      ioctl(ctx->playfd, AUDIOIOC_RELEASE, 0);
1110	    }
1111	
1112	  if (ctx->mq_open)
1113	    {
1114	      mq_close(ctx->mq);
1115	      mq_unlink(ctx->mqname);
1116	    }
1117	
1118	  if (ctx->recfd >= 0)
1119	    {
1120	      close(ctx->recfd);
1121	    }
1122	
1123	  if (ctx->playfd >= 0)
1124	    {
1125	      close(ctx->playfd);
1126	    }
1127	
1128	  memset(ctx, 0, sizeof(*ctx));
1129	  ctx->recfd  = -1;
1130	  ctx->playfd = -1;
1131	}
