1133	/* Which int16 of each pair carries the microphone -- 0 or 1.
1134	 *
1135	 * One slot of the two is always dead (see MIC_STRIDE), but WHICH one is not
1136	 * fixed, and this is the single most important thing in this file to not
1137	 * "simplify" later.  It does not merely vary between builds -- build 52 saw it
1138	 * flip BETWEEN CAPTURES INSIDE ONE BOOT:
1139	 *
1140	 *   [1/3] live slot 0 of 2   ->  yes 0.996
1141	 *   [2/3] live slot 0 of 2   ->  no  0.750
1142	 *   [3/3] live slot 1 of 2   ->  silence, correctly rejected
1143	 *
1144	 * Every capture re-arms RX, and the first sample lands on whichever slot the
1145	 * frame happens to be at when it does.  Hardcoding slot 0 -- the obvious
1146	 * reading of the first two captures -- would have made capture 3 come back all
1147	 * zeros and look exactly like a dead microphone.
1148	 *
1149	 * So it is measured, per capture, off the first buffer that carries anything.
1150	 *
1151	 * Exact zeros are the discriminator, not level.  The dead slot is zero to the
1152	 * bit, while the live slot carries an ADC noise floor even in a silent room --
1153	 * a silent build-50 capture read -1, -1, -2, 1, 5, -1, 57, -16.  A ceiling on
1154	 * amplitude would confuse the two during silence; counting exact zeros does
1155	 * not.  Ties go to slot 0, which is where es8311_start() puts the ADC
1156	 * (GPIO_REG44 = 0x50, ADC left / DAC right).
1157	 */
1158	
1159	static int mic_data_phase(const int16_t *src, size_t nsrc)
1160	{
1161	  size_t live[2] =
1162	    {
1163	      0, 0
1164	    };
1165	
1166	  size_t i;
1167	
1168	  for (i = 0; i < nsrc; i++)
1169	    {
1170	      if (src[i] != 0)
1171	        {
1172	          live[i & 1]++;
1173	        }
1174	    }
1175	
1176	  /* An all-zero buffer names no slot.  RX delivers a few of these while it
1177	   * warms up -- build 51's first capture opened with three of them -- and
1178	   * deciding on one would be a coin flip dressed up as a measurement.  The
1179	   * caller keeps asking until a buffer has something in it; until then the
1180	   * data is zeros whichever slot it is read from, so nothing is lost.
1181	   */
1182	
