1509	/* Subtract the mean.  Build 41 measured dc = -8585 on a 32767 scale -- a
1510	 * quarter of full range spent on a constant offset, which both eats headroom
1511	 * on one side (asymmetric clipping) and shows up as a large DC bin the
1512	 * feature front end never expects.  Cheap to fix here and it keeps the driver
1513	 * untouched.
1514	 */
1515	
1516	static void mic_dcblock(int16_t *audio, size_t nsamples)
1517	{
1518	  long sum = 0;
1519	  long dc;
1520	  size_t i;
1521	
1522	  if (nsamples == 0)
1523	    {
1524	      return;
1525	    }
1526	
1527	  for (i = 0; i < nsamples; i++)
1528	    {
1529	      sum += audio[i];
1530	    }
1531	
1532	  dc = sum / (long)nsamples;
1533	  if (dc == 0)
1534	    {
1535	      return;
1536	    }
1537	
1538	  for (i = 0; i < nsamples; i++)
1539	    {
1540	      long v = (long)audio[i] - dc;
1541	
1542	      audio[i] = (int16_t)(v > 32767 ? 32767 : (v < -32768 ? -32768 : v));
1543	    }
1544	
1545	  micinfo("mic: removed dc %ld\n", dc);
1546	}
