1548	/* Integer square root, so this costs no libm and no float formatting. */
1549	
1550	static unsigned long mic_isqrt(unsigned long long v)
1551	{
1552	  unsigned long long rem = 0;
1553	  unsigned long long root = 0;
1554	  int i;
1555	
1556	  for (i = 0; i < 32; i++)
1557	    {
1558	      root <<= 1;
1559	      rem = (rem << 2) | (v >> 62);
1560	      v <<= 2;
1561	
1562	      if (root < rem)
1563	        {
1564	          rem -= root | 1;
1565	          root += 2;
1566	        }
1567	    }
1568	
1569	  return (unsigned long)(root >> 1);
1570	}
