315	/* Find a record-capable and a playback-capable node under /dev/audio.
316	 *
317	 * Done by capability rather than by name: the device names come from the
318	 * board's audio registration, which lives in the VM board tree, and a wrong
319	 * guess would present as ENOENT at run time for no good reason.
320	 */
321	
322	static int mic_find_devices(char *inpath, char *outpath, size_t len)
323	{
324	  struct audio_caps_s caps;
325	  struct dirent *entry;
326	  char path[MIC_PATH_MAX];
327	  DIR *dirp;
328	  int found = 0;
329	  int fd;
330	
331	  inpath[0]  = '\0';
332	  outpath[0] = '\0';
333	
334	  dirp = opendir("/dev/audio");
335	  if (dirp == NULL)
336	    {
337	      printf("mic: cannot open /dev/audio: %d\n", errno);
338	      return -errno;
339	    }
340	
341	  while ((entry = readdir(dirp)) != NULL)
342	    {
343	      snprintf(path, sizeof(path), "/dev/audio/%s", entry->d_name);
344	
345	      fd = open(path, O_RDWR | O_CLOEXEC);
346	      if (fd < 0)
347	        {
348	          continue;
349	        }
350	
351	      memset(&caps, 0, sizeof(caps));
352	      caps.ac_len     = sizeof(caps);
353	      caps.ac_type    = AUDIO_TYPE_QUERY;
354	      caps.ac_subtype = AUDIO_TYPE_QUERY;
355	
356	      if (ioctl(fd, AUDIOIOC_GETCAPS, (unsigned long)&caps) == caps.ac_len)
357	        {
358	          /* ONE ROLE PER NODE -- an else-if chain, exactly as nxlooper does
359	           * in nxlooper_opendevice().  That is not incidental style.
360	           *
361	           * This board exposes two nodes: /dev/audio/pcm0, which reports BOTH
362	           * directions, and /dev/audio/pcm_in0, which is the record side.
363	           * Treating "reports both" as "usable for both" looks reasonable and
364	           * is wrong -- it claims pcm0 twice, so the capture opens and
365	           * reserves one device through two fds, pcm_in0 is never touched,
366	           * and RX never delivers a single buffer (timed out with 0/32000).
367	           *
368	           * The chain is order-independent here: whichever of the two is
369	           * enumerated first, pcm0 ends up on playback and pcm_in0 on record.
370	           */
371	
372	          if (outpath[0] == '\0' &&
373	              (caps.ac_controls.b[0] & AUDIO_TYPE_OUTPUT) != 0)
374	            {
375	              strlcpy(outpath, path, len);
376	              found++;
377	            }
378	          else if (inpath[0] == '\0' &&
379	                   (caps.ac_controls.b[0] & AUDIO_TYPE_INPUT) != 0)
380	            {
381	              strlcpy(inpath, path, len);
382	              found++;
383	            }
384	        }
385	
386	      close(fd);
387	
388	      if (inpath[0] != '\0' && outpath[0] != '\0')
389	        {
390	          break;
391	        }
392	    }
393	
394	  closedir(dirp);
395	
396	  if (inpath[0] == '\0' || outpath[0] == '\0')
397	    {
398	      printf("mic: need both a record and a playback node "
399	             "(in='%s' out='%s')\n", inpath, outpath);
400	      return -ENODEV;
401	    }
402	
403	  /* Cannot happen with the chain above, but say so loudly rather than hang
404	   * for five seconds if the board ever registers a single full-duplex node.
405	   */
406	
407	  if (strcmp(inpath, outpath) == 0)
408	    {
409	      printf("mic: record and playback resolved to the same node (%s)\n",
410	             inpath);
411	      return -ENODEV;
412	    }
413	
414	  micinfo("mic: record=%s playback=%s\n", inpath, outpath);
415	  return found;
416	}
