The comment block above it documents the full b63/b64/b65 failure history (1.5s → DRAM overflow; 1.25s → capture never returns; 1.25s @ 22 bufs → same).

`voice_align()` (line ~2190-2225), added b63, currently inert:
```c
static int voice_align(const int16_t *audio, int n, int win)
{
  uint32_t sum  = 0;
  uint32_t best;
  int      besti = 0;
  int      i;

  if (n <= win)
    {
      return 0;
    }

  for (i = 0; i < win; i++)
    {
      sum += (uint32_t)(audio[i] < 0 ? -audio[i] : audio[i]);
    }

  best = sum;

  for (i = win; i < n; i++)
    {
      sum += (uint32_t)(audio[i] < 0 ? -audio[i] : audio[i]);
      sum -= (uint32_t)(audio[i - win] < 0 ? -audio[i - win] : audio[i - win]);

      if (sum > best)
        {
          best  = sum;
          besti = i - win + 1;
        }
    }

  return besti;
}
