/* Is this label one of the step's legal answers?  Only the wrong-word message
 * needs to ask: best_of() can never return a non-member, so every other test
 * in vsched_step() is against a word that is legal by construction. */

static int vsched_legal(const int *words, int nwords, int label)
{
  int i;

  for (i = 0; i < nwords; i++)
    {
      if (words[i] == label)
        {
          return 1;
        }
    }

  return 0;
}

